CREATE VIEW v_race_results AS SELECT results.resultId AS result_id, results.number AS car_number, results.grid, results.position, results.positionOrder AS position_order, results.points, results.laps, results.fastestLap AS fastest_lap, results.fastestLapSpeed AS fastest_lap_speed, drivers.driverId AS driver_id, drivers.driverRef AS driver_ref, drivers.forename AS driver_forename, drivers.surname AS driver_surname, drivers.nationality AS driver_nationality, constructors.constructorId AS constructor_id, constructors.name AS constructor_name, races.raceId AS race_id, races.year AS race_year, races.round AS race_round, races.name AS race_name, races.date AS race_date, status.status AS result_status, results.raceId, results.driverId, results.constructorId, results.time, results.rank, results.fastestLapTime, results.statusId, races.circuitId, races.time AS races_time, drivers.number, drivers.code, drivers.dob, drivers.url, constructors.constructorRef, constructors.nationality, constructors.url AS constructors_url, status.statusId AS status_statusId FROM results LEFT JOIN races ON results.raceId = races.raceId LEFT JOIN drivers ON results.driverId = drivers.driverId LEFT JOIN constructors ON results.constructorId = constructors.constructorId LEFT JOIN status ON results.statusId = status.statusId;

CREATE VIEW v_race_circuits AS SELECT races.raceId AS race_id, races.year AS race_year, races.round AS race_round, races.name AS race_name, races.date AS race_date, circuits.circuitId AS circuit_id, circuits.circuitRef AS circuit_ref, circuits.name AS circuit_name, circuits.location AS circuit_location, circuits.country AS circuit_country, races.circuitId, races.time, circuits.lat, circuits.lng FROM races LEFT JOIN circuits ON races.circuitId = circuits.circuitId;

CREATE VIEW v_qualifying_driver AS SELECT qualifying.qualifyId AS qualify_id, qualifying.position AS qualify_position, qualifying.q1, qualifying.q2, qualifying.q3, drivers.driverId AS driver_id, drivers.forename AS driver_forename, drivers.surname AS driver_surname, constructors.name AS constructor_name, races.raceId AS race_id, races.name AS race_name, races.year AS race_year, qualifying.raceId, qualifying.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.dob, drivers.nationality, drivers.url, races.circuitId, races.date, races.time, constructors.constructorId, constructors.constructorRef, constructors.nationality AS constructors_nationality, constructors.url AS constructors_url FROM qualifying LEFT JOIN drivers ON qualifying.driverId = drivers.driverId LEFT JOIN races ON qualifying.raceId = races.raceId LEFT JOIN constructors ON qualifying.constructorId = constructors.constructorId;

CREATE VIEW v_circuits_races_results AS SELECT circuits.circuitId, circuits.circuitRef, circuits.name, circuits.location, circuits.country, circuits.lat, circuits.lng, races.raceId, races.year, races.circuitId AS races_circuitId, races.name AS races_name, races.date, races.time, results.raceId AS results_raceId, results.driverId, results.constructorId, results.positionOrder, results.laps, results.time AS results_time, results.fastestLap, results.rank, results.fastestLapTime, results.fastestLapSpeed, results.statusId FROM circuits INNER JOIN races ON circuits.circuitid = races.circuitid INNER JOIN results ON races.raceid = results.raceid;

CREATE VIEW v_constructorresults_constructors AS SELECT constructorResults.raceId, constructorResults.constructorId, constructorResults.points, constructors.constructorId AS constructors_constructorId, constructors.constructorRef, constructors.name, constructors.nationality, constructors.url FROM constructorResults INNER JOIN constructors ON constructorResults.constructorid = constructors.constructorid;

CREATE VIEW v_constructorresults_constructors_races AS SELECT constructorResults.raceId, constructorResults.constructorId, constructorResults.points, constructors.constructorId AS constructors_constructorId, constructors.constructorRef, constructors.name, constructors.nationality, constructors.url, races.raceId AS races_raceId, races.year, races.circuitId, races.name AS races_name, races.date, races.time FROM constructorResults INNER JOIN constructors ON constructorResults.constructorid = constructors.constructorid INNER JOIN races ON constructorResults.raceid = races.raceid;

CREATE VIEW v_constructors_constructorstandings AS SELECT constructors.constructorId, constructors.constructorRef, constructors.name, constructors.nationality, constructors.url, constructorStandings.raceId, constructorStandings.constructorId AS constructorStandings_constructorId, constructorStandings.points FROM constructors INNER JOIN constructorStandings ON constructors.constructorid = constructorStandings.constructorid;

CREATE VIEW v_drivers_driverstandings AS SELECT drivers.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, driverStandings.driverStandingsId, driverStandings.raceId, driverStandings.driverId AS driverStandings_driverId, driverStandings.points, driverStandings.position, driverStandings.wins FROM drivers INNER JOIN driverStandings ON drivers.driverid = driverStandings.driverid;

CREATE VIEW v_drivers_driverstandings_races AS SELECT drivers.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, driverStandings.driverStandingsId, driverStandings.raceId, driverStandings.driverId AS driverStandings_driverId, driverStandings.points, driverStandings.position, driverStandings.wins, races.raceId AS races_raceId, races.year, races.circuitId, races.name, races.date, races.time FROM drivers INNER JOIN driverStandings ON drivers.driverid = driverStandings.driverid INNER JOIN races ON driverStandings.raceid = races.raceid;

CREATE VIEW v_drivers_laptimes AS SELECT drivers.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, lapTimes.raceId, lapTimes.driverId AS lapTimes_driverId, lapTimes.time, lapTimes.milliseconds FROM drivers INNER JOIN lapTimes ON drivers.driverid = lapTimes.driverid;

CREATE VIEW v_drivers_laptimes_races AS SELECT drivers.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, lapTimes.raceId, lapTimes.driverId AS lapTimes_driverId, lapTimes.time, lapTimes.milliseconds, races.raceId AS races_raceId, races.year, races.circuitId, races.name, races.date, races.time AS races_time FROM drivers INNER JOIN lapTimes ON drivers.driverid = lapTimes.driverid INNER JOIN races ON lapTimes.raceid = races.raceid;

CREATE VIEW v_drivers_pitstops AS SELECT drivers.driverId, drivers.driverRef, drivers.number, drivers.code, drivers.forename, drivers.surname, drivers.dob, drivers.nationality, drivers.url, pitStops.driverId AS pitStops_driverId, pitStops.duration FROM drivers INNER JOIN pitStops ON drivers.driverid = pitStops.driverid;

CREATE VIEW v_laptimes AS SELECT lapTimes.raceId, lapTimes.driverId, lapTimes.time, lapTimes.milliseconds FROM lapTimes;

CREATE VIEW v_races_seasons AS SELECT races.raceId, races.year, races.circuitId, races.name, races.date, races.time, seasons.year AS seasons_year, seasons.url FROM races INNER JOIN seasons ON races.year = seasons.year;
